// Callback style:
fs.readFile(path, (err, data) => {
  if (err) return next(err); // return prevents double-calls
  process(data);
});

// Promise/async style:
try {
  const data = await fs.promises.readFile(path);
  process(data);
} catch (err) {
  next(err);
}

// EventEmitter style:
socket.on('error', (err) => logger.error(err)); // required listener

app.use(requestLogger);                    // 1st: logs everything
app.use(express.json());                   // 2nd: parses bodies
app.use('/api', apiRouter);                // scoped routes

app.use((req, res) => res.status(404).end());       // fallthrough
app.use((err, req, res, _next) => {                 // error handler: 4 args!
  console.error(err);
  res.status(500).json({ error: 'Internal error' });
});

function requestLogger(req, _res, next) {
  console.log(`${req.method} ${req.url}`);
  next();
}

